    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '61: A "Couvelaire Uterus" is a complication of severe Abruption where:', '["The uterus ruptures", "Blood extravasates into the myometrium, giving it a purplish/blue appearance", "The uterus stays small", "Infection occurs"]', 1, 'Often leads to uterine atony. (Williams)'),
    (v_topic_id, '62: "Vasa Previa" differs from Placenta Previa in that the bleeding is primarily:', '["Maternal", "Fetal", "Amniotic", "Both"]', 1, 'Since the vessels are fetal, a small amount of bleeding can quickly lead to fetal exsanguination and death. (Beckmann)'),
    (v_topic_id, '63: The "Apt test" is used to:', '["Check for labor", "Differentiate fetal from maternal blood in vaginal bleeding", "Check for Down syndrome", "Test for glucose"]', 1, 'Uses alkali denaturation of hemoglobin. (Williams)'),
    (v_topic_id, '64: Management of a stable "Placental Abruption" at 34 weeks?', '["Immediate C-section", "Expectant management if mother and fetus are stable", "Wait until 40 weeks", "Antibiotics"]', 1, 'May allow for steroids and further maturity. (ACOG)'),
    (v_topic_id, '65: Which of the following is a classic risk factor for "Abruption" related to substance use?', '["Alcohol", "Cocaine and Tobacco", "Caffeine", "Marijuana"]', 1, 'Vasoconstriction leads to placental separation. (Beckmann)'),
    (v_topic_id, '66: A "Concealed Abruption" is one where:', '["The bleeding is visible", "The blood is trapped behind the placenta and no vaginal bleeding is seen", "The baby is small", "The placenta is missing"]', 1, 'Can lead to severe pain and fetal distress despite no visible blood. (Williams)'),
    (v_topic_id, '67: "Multiple Gestation" (Twins) increases the risk of which maternal complication?', '["Pre-eclampsia and GDM", "Iron deficiency anemia", "Postpartum hemorrhage (atony)", "All of the above"]', 3, 'Multiples put higher physiological stress on the mother. (ACOG)'),
    (v_topic_id, '68: "Dizygotic" twins (fraternal) result from:', '["One egg splitting", "Two separate eggs fertilized by two separate sperm", "One sperm fertilizing two eggs", "Genetic mutation"]', 1, 'Most common type of twins. (Williams)'),
    (v_topic_id, '69: "Monozygotic" twins (identical) splitting on days 4-8 after fertilization result in:', '["Dichorionic/Diamniotic twins", "Monochorionic/Diamniotic twins", "Monochorionic/Monoamniotic twins", "Conjoined twins"]', 1, 'Share a placenta but have separate sacs. (Beckmann)'),
    (v_topic_id, '70: Which type of twins are at risk for "Twin-to-Twin Transfusion Syndrome" (TTTS)?', '["Dichorionic/Diamniotic", "Monochorionic", "Fraternal twins", "All of them"]', 1, 'Only monochorionic twins have vascular anastomoses. (ACOG)'),
    (v_topic_id, '71: In TTTS, the "Donor" twin typically has:', '["Polyhydramnios and Large size", "Oligohydramnios, Anemia, and Growth restriction", "High blood pressure", "No sacs"]', 1, 'Shunts blood to the recipient. (Williams)'),
    (v_topic_id, '72: "Monochorionic/Monoamniotic" (Mo-Mo) twins are at extremely high risk for:', '["Twin-to-Twin transfusion", "Umbilical cord entanglement", "Pre-eclampsia", "Both A and B"]', 3, 'Requires intensive monitoring and early delivery (32-34 weeks). (ACOG)'),
    (v_topic_id, '73: What is the recommended mode of delivery for twins if Twin A is vertex and Twin B is vertex?', '["C-section only", "Trial of vaginal delivery", "Wait until 42 weeks", "Forceps for both"]', 1, 'Vaginal delivery is preferred for vertex-vertex. (ACOG)'),
    (v_topic_id, '74: "Intrauterine Growth Restriction" (IUGR) is defined as EFW below which percentile?', '["5th", "10th", "25th", "50th"]', 1, 'Commonly due to placental insufficiency. (Williams)'),
    (v_topic_id, '75: "Symmetric" IUGR (head and body equally small) is most likely due to:', '["Late pregnancy HTN", "Early 1st-trimester insult (infection or aneuploidy)", "Smoking", "Poor nutrition"]', 1, 'Occurs during the hyperplastic phase of growth. (Beckmann)'),
    (v_topic_id, '76: "Asymmetric" IUGR (head-sparing) is most likely due to:', '["Aneuploidy", "Placental insufficiency (HTN, Smoking, etc.) in the 2nd/3rd trimesters", "Early infection", "Genetics"]', 1, 'Fetal "brain-sparing" effect. (Williams)'),
    (v_topic_id, '77: Which Doppler study is the primary tool for monitoring a fetus with IUGR?', '["Uterine artery", "Umbilical Artery Doppler", "MCA Doppler", "Renal Doppler"]', 1, 'Increasing resistance or reversed end-diastolic flow suggests impending fetal compromise. (ACOG)'),
    (v_topic_id, '78: Management of IUGR at 38 weeks with normal Dopplers?', '["Wait until 40 weeks", "Delivery (Induction)", "Immediate C-section", "Bed rest"]', 1, 'Delivery is indicated by 38-39 weeks even in stable IUGR. (ACOG)'),
    (v_topic_id, '79: "Fetal Macrosomia" is defined as a birth weight > _____ grams.', '["3500", "4000-4500 (depending on definition)", "5000", "3000"]', 1, 'Associated with shoulder dystocia. (Beckmann)'),
    (v_topic_id, '80: "Oligohydramnios" in IUGR is due to:', '["Fetal dehydration", "Fetal redistribution of blood flow away from kidneys, leading to decreased urine", "Mother not drinking", "Placental bleeding"]', 1, 'Marker of chronic hypoxia. (Williams)'),
    (v_topic_id, '81: "Rh Alloimmunization" occurs when:', '["Rh-negative mother has an Rh-positive fetus", "Rh-positive mother has an Rh-negative fetus", "Both are Rh-negative", "Both are Rh-positive"]', 0, 'Maternal antibodies (Anti-D) cross the placenta and destroy fetal RBCs. (ACOG)'),
    (v_topic_id, '82: When is "RhoGAM" (300 mcg) routinely administered during pregnancy for Rh-negative women?', '["12 weeks", "28 weeks", "Birth only", "Postpartum only"]', 1, 'Prophylaxis to prevent sensitization from late-trimester micro-hemorrhages. (ACOG)'),
    (v_topic_id, '83: A "Kleihauer-Betke" (KB) test is performed postpartum to:', '["Check for Rh status", "Quantify the amount of fetal-to-maternal hemorrhage to calculate RhoGAM dose", "Screen for Down syndrome", "Check for jaundice"]', 1, 'One dose of RhoGAM covers ~30 mL of fetal whole blood. (Williams)'),
    (v_topic_id, '84: In a sensitized mother, which ultrasound measurement monitors for fetal anemia?', '["BPD", "Middle Cerebral Artery (MCA) Peak Systolic Velocity", "Femur length", "Abdominal circumference"]', 1, 'Increased velocity = thinner blood (Anemia). (ACOG)'),
    (v_topic_id, '85: A "Critical Titer" (usually 1:8 to 1:32) in Rh-sensitization indicates:', '["The baby is safe", "Significant risk of Hemolytic Disease of the Fetus and Newborn (HDFN)", "The mother is immune", "The test is invalid"]', 1, 'Requires intensive fetal monitoring with Doppler. (Beckmann)'),
    (v_topic_id, '86: "Hydrops Fetalis" is defined by fluid in _____ or more fetal compartments.', '["1", "2 (e.g., ascites + skin edema)", "3", "All"]', 1, 'Final common pathway of severe fetal heart failure/anemia. (Williams)'),
    (v_topic_id, '87: "Post-term" pregnancy is defined as reaching _____ weeks.', '["40", "41", "42", "43"]', 2, '>= 42 0/7 weeks. (ACOG)'),
    (v_topic_id, '88: What is the most common cause of a "Post-term" diagnosis?', '["Placental issues", "Fetal anomalies", "Inaccurate dating (incorrect LMP)", "Obesity"]', 2, 'Standard dating error is the #1 cause. (Beckmann)'),
    (v_topic_id, '89: Post-term pregnancies are at increased risk for:', '["Macrosomia", "Oligohydramnios", "Meconium Aspiration Syndrome", "All of the above"]', 3, 'Placental function declines after 42 weeks. (Williams)'),
    (v_topic_id, '90: Management of a post-term patient? (ACOG recommendation)', '["Induction at 41-42 weeks", "Wait until 43 weeks", "Induction at 40 weeks for everyone", "Daily NST only"]', 0, 'Induction is recommended between 41 and 42 weeks. (ACOG)'),
    (v_topic_id, '91: "Hyperemesis Gravidarum" (HG) is distinguished from morning sickness by:', '["Nausea", "Weight loss (> 5%), ketonuria, and electrolyte imbalances", "Vomiting once a day", "Headache"]', 1, 'Severe form requiring IV fluids and anti-emetics. (ACOG)'),
    (v_topic_id, '92: First-line medication for nausea and vomiting in pregnancy?', '["Ondansetron", "Pyridoxine (Vitamin B6) +/- Doxylamine", "Promethazine", "Metoclopramide"]', 1, 'Known as Diclegis/Bonjesta. (ACOG)'),
    (v_topic_id, '93: "Intrahepatic Cholestasis of Pregnancy" (ICP) presents with:', '["RUQ pain", "Severe pruritus (itching) on palms and soles with elevated bile acids", "Jaundice only", "Rash"]', 1, 'High risk of stillbirth; deliver at 36-37 weeks. (Williams)'),
    (v_topic_id, '94: Treatment for ICP to reduce bile acids and itching?', '["Steroid cream", "Ursodeoxycholic acid (Ursodiol)", "Antihistamines only", "Bed rest"]', 1, 'UDCA improves symptoms and bile acid levels. (Beckmann)'),
    (v_topic_id, '95: "Pruritic Urticarial Papules and Plaques of Pregnancy" (PUPPP) is:', '["Dangerous for the baby", "Benign but very itchy rash starting in the striae", "A sign of liver failure", "Fungal"]', 1, 'Usually resolves immediately postpartum. (Williams)'),
    (v_topic_id, '96: "Acute Fatty Liver of Pregnancy" (AFLP) is a medical emergency characterized by:', '["Hypoglycemia, liver failure, and DIC in the 3rd trimester", "Mild jaundice", "Weight gain", "High BP only"]', 0, 'Requires immediate delivery and intensive care. (ACOG)'),
    (v_topic_id, '97: AFLP is associated with a deficiency in which fetal enzyme?', '["G6PD", "Long-chain 3-hydroxyacyl-CoA dehydrogenase (LCHAD)", "PKU", "Lactase"]', 1, 'Fetal LCHAD deficiency leads to maternal liver toxicity. (Williams)'),
    (v_topic_id, '98: "Pyelonephritis" in pregnancy is more common on the right side because:', '["The right kidney is larger", "Dextrorotation of the uterus and the right ovarian vein complex compress the right ureter", "Bacteria like the right side", "None"]', 1, 'Progesterone also causes smooth muscle relaxation and hydroureter. (Beckmann)'),
    (v_topic_id, '99: Treatment for "Pyelonephritis" in a pregnant patient?', '["Oral Amoxicillin", "Hospitalization for IV antibiotics (e.g., Ceftriaxone) and IV fluids", "Wait and see", "Surgery"]', 1, 'High risk of maternal sepsis and preterm labor. (Williams)'),
    (v_topic_id, '100: "Appendicitis" in pregnancy may present with pain in which location as gestation progresses?', '["Right Lower Quadrant", "Right Upper Quadrant (due to appendix displacement)", "Left Lower Quadrant", "Periumbilical only"]', 1, 'Appendix is pushed up by the enlarging uterus. (Beckmann)'),
    (v_topic_id, '101: "Mitral Stenosis" (often from Rheumatic Heart Disease) is particularly dangerous in pregnancy because:', '["It causes diabetes", "Tachycardia and increased blood volume can lead to pulmonary edema/heart failure", "It causes twins", "It leads to abruption"]', 1, 'Requires beta-blockade to maintain diastolic filling time. (Williams)'),
    (v_topic_id, '102: "Peripartum Cardiomyopathy" is defined as heart failure occurring:', '["In the 1st trimester", "In the last month of pregnancy or first 5 months postpartum with no other cause", "Before pregnancy", "After 1 year"]', 1, 'Ejection fraction is typically < 45%. (ACOG)'),
    (v_topic_id, '103: A woman with "Mechanical Heart Valves" should be anticoagulated in pregnancy with:', '["Warfarin (Coumadin) in the 1st trimester", "Low Molecular Weight Heparin (LMWH) or Unfractionated Heparin", "Aspirin only", "No anticoagulation"]', 1, 'Warfarin is teratogenic (nasal hypoplasia/bone defects) in the 1st trimester. (ACOG)'),
    (v_topic_id, '104: Most common cause of "Hyperthyroidism" in pregnancy?', '["Toxic nodule", "Graves Disease", "Gestational Transient Thyrotoxicosis (due to high hCG)", "Cancer"]', 1, 'hCG can also stimulate the TSH receptor, leading to transient hyperthyroidism. (Williams)'),
    (v_topic_id, '105: Preferred drug for "Hyperthyroidism" in the 1st trimester?', '["Methimazole", "Propylthiouracil (PTU)", "Radioactive iodine", "L-thyroxine"]', 1, 'PTU is preferred in 1st trimester due to Methimazole-associated embryopathy (aplasia cutis). (ACOG)'),
    (v_topic_id, '106: "Hypothyroidism" in pregnancy requires:', '["Decreasing L-thyroxine dose", "Increasing L-thyroxine dose (often by 30%)", "Stopping meds", "Changing to PTU"]', 1, 'Thyroid requirements increase early in pregnancy. (Beckmann)'),
    (v_topic_id, '107: "Systemic Lupus Erythematosus" (SLE) in pregnancy increases the risk of:', '["Pre-eclampsia and IUGR", "Congenital Heart Block (if anti-Ro/La positive)", "Maternal Lupus flares", "All of the above"]', 3, 'Requires multidisciplinary care. (Williams)'),
    (v_topic_id, '108: "Antiphospholipid Syndrome" (APS) is a common cause of:', '["Recurrent pregnancy loss and venous/arterial thrombosis", "Diabetes", "Twins", "Large babies"]', 0, 'Treated with Heparin + Aspirin in pregnancy. (ACOG)'),
    (v_topic_id, '109: "Asthma" management in pregnancy?', '["Stop all meds", "Same as non-pregnant; keep controlled to avoid fetal hypoxia", "Steroids only", "Albuterol only"]', 1, 'The "Rule of Thirds": 1/3 improve, 1/3 stay same, 1/3 worsen. (Beckmann)'),
    (v_topic_id, '110: "Bariatric Surgery" patients should wait how long before getting pregnant?', '["1 month", "12-18 months", "No wait", "Never"]', 1, 'Until weight loss stabilizes and nutritional status is optimized. (ACOG)'),
    (v_topic_id, '111: "Thyroid Storm" in pregnancy is a medical emergency. Treatment includes:', '["PTU, Iodine, Propranolol, and Dexamethasone", "L-thyroxine", "Antibiotics", "Fluids only"]', 0, 'Standard multi-drug management to block T4 synthesis and peripheral conversion. (Williams)'),
    (v_topic_id, '112: "Asymptomatic Bacteriuria" is treated in pregnancy even without symptoms to prevent:', '["Miscarriage", "Pyelonephritis and Preterm Birth", "Diabetes", "HTN"]', 1, 'Standard screening at the 1st prenatal visit. (ACOG)'),
    (v_topic_id, '113: Which anticoagulant is the "Drug of Choice" for DVT/PE in pregnancy?', '["Warfarin", "LMWH (Enoxaparin)", "Apixaban (Eliquis)", "Aspirin"]', 1, 'Does not cross the placenta and is easy to reverse. (Beckmann)'),
    (v_topic_id, '114: "Appendicitis" is the most common non-obstetric surgical emergency in pregnancy. Diagnosis is best confirmed by:', '["Clinical exam only", "Ultrasound or MRI (to avoid radiation)", "CT Scan with contrast", "Wait and see"]', 1, 'MRI is preferred if US is inconclusive. (ACOG)'),
    (v_topic_id, '115: "Cholecystitis" in pregnancy is initially managed with:', '["Immediate surgery for everyone", "Conservative management (fluids, antibiotics, NPO) and surgery if fails or delayed to 2nd trimester", "Dissolving stones", "None"]', 1, 'The 2nd trimester is the safest time for non-emergency surgery. (Williams)'),
    (v_topic_id, '116: "HIV" positive mothers can reduce transmission to < 1% by:', '["HAART therapy and viral load < 1000 at delivery", "Vaginal delivery only", "Breastfeeding", "No meds"]', 0, 'Viral load > 1000 warrants C-section. (ACOG)'),
    (v_topic_id, '117: Which HIV medication is traditionally avoided in the first weeks of pregnancy due to neural tube defect concerns (though recent data is reassuring)?', '["Zidovudine (AZT)", "Dolutegravir", "Efavirenz", "Tenofovir"]', 1, 'Concerns about Dolutegravir have largely been minimized by larger studies. (WHO/ACOG)'),
    (v_topic_id, '118: "Parvovirus B19" infection in the 1st half of pregnancy requires which follow-up?', '["No follow up", "Serial ultrasounds for 10-12 weeks to monitor for fetal hydrops", "Immediate delivery", "Amniocentesis"]', 1, 'If hydrops found, intrauterine blood transfusion may be needed. (Williams)'),
    (v_topic_id, '119: "Placenta Accreta" is invasion of the placenta into the:', '["Myometrium", "Bladder", "Rectum", "Vagina"]', 0, 'Accreta (attach), Increta (into), Percreta (through). (Beckmann)'),
    (v_topic_id, '120: Definitive management for Placenta Accreta Spectrum (PAS)?', '["Manual removal", "Planned C-hyst (Cesarean Hysterectomy)", "Oxytocin", "Methotrexate"]', 1, 'The gold standard for management. (ACOG)');
